use dsp::FskDetector;use ec::hdlc::{Decoder,Fcs};
fn main(){let path=std::env::args().nth(1).unwrap();let b=std::fs::read(path).unwrap();let mut p=12;let data=loop{let n=u32::from_le_bytes(b[p+4..p+8].try_into().unwrap()) as usize;if &b[p..p+4]==b"data"{break &b[p+8..p+8+n];}p+=8+n+(n&1);};let channel=std::env::args().nth(2).unwrap_or("0".into()).parse::<usize>().unwrap();let (space,mark)=if channel==0 {(1850.0,1650.0)} else {(1180.0,980.0)};let mut detector=FskDetector::new(space,mark,300.0,8000.0);let mut dec=Decoder::new(Fcs::Bits16).with_max_octets(66).with_minimum_payload(1);let(mut clock,mut last)=(0.0,true);for(i,f)in data.chunks_exact(4).enumerate(){let bit=detector.feed(i16::from_le_bytes([f[channel*2],f[channel*2+1]]) as f64/32768.0)>0.0;if !detector.carrier(){clock=0.0;last=bit;continue;}if bit!=last{clock=8000.0/600.0;last=bit;}clock-=1.0;if clock>0.0{continue;}clock+=8000.0/300.0;if let Some(m)=dec.feed(bit){println!("{:.4}: {:02x?}",i as f64/8000.0,m);}}}
